import os
import stripe
from agents import function_tool
stripe.api_key = os.environ['STRIPE_API_KEY']


def _customer_is_active(customer_id: str) -> bool:
    # Read-only lookup of the customer record in Stripe
    try:
        cust = stripe.Customer.retrieve(customer_id)
    except stripe.error.InvalidRequestError:
        return False
    return not getattr(cust, 'deleted', False)


@function_tool
def charge_ticket_upgrade(customer_id: str, amount_cents: int, ticket_id: str) -> dict:
    if not customer_id.startswith('cus_'):
        return {'ok': False, 'error': 'invalid customer id'}
    if amount_cents <= 0 or amount_cents > 500000:
        return {'ok': False, 'error': 'amount out of range'}
    if not ticket_id.strip():
        return {'ok': False, 'error': 'ticket id required'}
    if not _customer_is_active(customer_id):
        return {'ok': False, 'error': 'customer not found'}
    pi = stripe.PaymentIntent.create(amount=amount_cents, currency='usd', customer=customer_id, confirm=True, off_session=True, metadata={'ticket_id': ticket_id, 'kind': 'upgrade'})
    return {'ok': True, 'payment_intent': pi.id, 'status': pi.status}
